create table public.question_drafts(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),author_id uuid not null,raw_text text not null,content jsonb not null,revision int not null default 1,foreign key(school_id,author_id) references memberships(school_id,id));
create table public.exam_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),teacher_id uuid not null,class_id uuid not null,title text not null,subject text not null,instructions text not null,opens_at timestamptz not null,closes_at timestamptz not null,duration_seconds int not null check(duration_seconds between 1 and 43200),last_start_at timestamptz,shuffle boolean not null default false,status text not null default 'published' check(status in ('published','cancelled','archived')),created_at timestamptz not null default now(),foreign key(school_id,teacher_id) references memberships(school_id,id),foreign key(school_id,class_id) references classes(school_id,id),unique(school_id,id),check(closes_at>opens_at),check(duration_seconds<=extract(epoch from closes_at-opens_at)));
create table public.exam_questions(school_id uuid not null,version_id uuid not null,id uuid not null,position int not null,type text not null check(type in ('mcq','boolean','match','blank','subjective')),maximum int not null check(maximum>0),content jsonb not null,primary key(version_id,id),foreign key(school_id,version_id) references exam_versions(school_id,id));
create table private.question_keys(school_id uuid not null,version_id uuid not null,question_id uuid not null,key jsonb not null,primary key(version_id,question_id),foreign key(version_id,question_id) references exam_questions(version_id,id));
create table public.exam_recipients(school_id uuid not null,version_id uuid not null,student_id uuid not null,extra_seconds int not null default 0 check(extra_seconds between 0 and 43200),closes_at timestamptz not null,exempt boolean not null default false,primary key(version_id,student_id),foreign key(school_id,version_id) references exam_versions(school_id,id),foreign key(school_id,student_id) references student_registry(school_id,student_id));
create table public.attempts(id uuid primary key default gen_random_uuid(),school_id uuid not null,version_id uuid not null,student_id uuid not null,started_at timestamptz not null default now(),deadline timestamptz not null,finalized_at timestamptz,status text not null default 'in_progress' check(status in ('in_progress','submitted','expired')),writer uuid not null,writer_epoch int not null default 1,display_order jsonb not null,receipt uuid,unique(version_id,student_id),unique(school_id,id),foreign key(version_id,student_id) references exam_recipients(version_id,student_id),foreign key(school_id,version_id) references exam_versions(school_id,id));
create index attempt_expiry on attempts(deadline) where status='in_progress';
create table public.answers(school_id uuid not null,attempt_id uuid not null,question_id uuid not null,response jsonb not null,revision int not null check(revision>0),saved_at timestamptz not null default now(),primary key(attempt_id,question_id),foreign key(school_id,attempt_id) references attempts(school_id,id));
create table private.grades(school_id uuid not null,attempt_id uuid not null,question_id uuid not null,objective_score int,ai_suggestion jsonb,final_score int,reviewer uuid,feedback text,revision int not null default 1,primary key(attempt_id,question_id),foreign key(school_id,attempt_id) references attempts(school_id,id));
create table public.results(id uuid primary key default gen_random_uuid(),school_id uuid not null,attempt_id uuid not null unique,student_id uuid not null,version_id uuid not null,revision int not null default 1,published_at timestamptz not null default now(),total int not null,maximum int not null,scores jsonb not null,foreign key(school_id,attempt_id) references attempts(school_id,id),foreign key(school_id,student_id) references memberships(school_id,id));
create table private.result_revisions(id bigint generated always as identity primary key,result_id uuid not null references results(id),revision int not null,snapshot jsonb not null,created_at timestamptz not null default now(),unique(result_id,revision));
create table public.integrity_events(id uuid primary key default gen_random_uuid(),school_id uuid not null,attempt_id uuid not null,student_id uuid not null,type text not null check(type in ('visibility_loss','fullscreen_exit','refresh','disconnect')),client_at timestamptz,received_at timestamptz not null default now(),foreign key(school_id,attempt_id) references attempts(school_id,id));
create table public.integrity_reviews(id uuid primary key default gen_random_uuid(),school_id uuid not null,attempt_id uuid not null,actor_id uuid not null,outcome text not null check(outcome in ('cleared','warning','invalidated','appeal')),reason text not null,created_at timestamptz not null default now(),foreign key(school_id,attempt_id) references attempts(school_id,id));
create function private.active_attempt() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.attempts where student_id=auth.uid() and status='in_progress' and deadline>now())$$;
create function private.learning_access() returns void language plpgsql security definer set search_path='' as $$begin if private.role()='student' and private.active_attempt() then raise exception 'ACTIVE_ATTEMPT_RESTRICTED' using errcode='42501';end if;end$$;
create function private.exam_teacher(v uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exam_versions where id=v and school_id=private.school() and private.role()='teacher' and teacher_id=auth.uid() and private.assigned(class_id,subject))$$;
create function private.can_exam(v uuid) returns boolean language sql stable security definer set search_path='' as $$select private.exam_teacher(v) or exists(select 1 from public.exam_recipients r where r.version_id=v and r.student_id=auth.uid() and r.school_id=private.school() and private.role()='student')$$;
-- SQL scoring is deliberately independent of display numbering.
create function private.objective_score(q jsonb,k jsonb,response jsonb) returns int language plpgsql immutable set search_path='' as $$declare n int:=0;u jsonb;a text;begin if q->>'type'='subjective' then return null;end if;if q->>'type' in ('mcq','boolean') then return case when response=k->'correct' then (q->>'max')::int else 0 end;end if;for u in select value from jsonb_array_elements(k->'units') loop if q->>'type'='match' then if response->>(u->>'id')=u->>'right' then n:=n+(u->>'max')::int;end if;else for a in select jsonb_array_elements_text(u->'alternatives') loop if lower(trim(response->>(u->>'id')))=lower(trim(a)) then n:=n+(u->>'max')::int;exit;end if;end loop;end if;end loop;return n;end$$;
create function public.publish_exam(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();v uuid;q jsonb;k jsonb;r jsonb;pos int:=0;c uuid:=(p->>'classId')::uuid;begin perform private.require_access(s,true);if private.role()<>'teacher' or not private.assigned(c,p->>'subject') then raise exception 'FORBIDDEN' using errcode='42501';end if;
insert into public.exam_versions(school_id,teacher_id,class_id,title,subject,instructions,opens_at,closes_at,duration_seconds,last_start_at,shuffle)values(s,auth.uid(),c,p->>'title',p->>'subject',p->>'instructions',(p->>'opensAt')::timestamptz,(p->>'closesAt')::timestamptz,(p->>'durationSeconds')::int,(p->>'lastStartAt')::timestamptz,(p->>'shuffle')::boolean)returning id into v;
if jsonb_array_length(p->'questions')<1 then raise exception 'EMPTY_PAPER';end if;
for q in select value from jsonb_array_elements(p->'questions') loop select value into k from jsonb_array_elements(p->'keys') where value->>'questionId'=q->>'id';if k is null then raise exception 'MISSING_KEY';end if;perform private.validate_question(q,k);
if q->>'type'='mcq' and not exists(select 1 from jsonb_array_elements(q->'options') o where o->'id'=k->'correct') then raise exception 'INVALID_KEY';end if;
if q->>'type'='boolean' and jsonb_typeof(k->'correct')<>'boolean' then raise exception 'INVALID_KEY';end if;
if q->>'type'='subjective' and (coalesce((select sum((x->>'max')::int) from jsonb_array_elements(k->'rubric') x),0)<>(q->>'max')::int or coalesce(k->>'reference','')='') then raise exception 'INVALID_RUBRIC';end if;
if q->>'type' in ('blank','match') and coalesce((select sum((x->>'max')::int) from jsonb_array_elements(k->'units') x),0)<>(q->>'max')::int then raise exception 'INVALID_UNITS';end if;
insert into public.exam_questions values(s,v,(q->>'id')::uuid,pos,q->>'type',(q->>'max')::int,jsonb_strip_nulls(jsonb_build_object('id',q->'id','type',q->'type','prompt',q->'prompt','section',q->'section','max',q->'max','primaryTopic',q->'primaryTopic','options',q->'options','left',q->'left','right',q->'right','blanks',q->'blanks','shuffleOptions',q->'shuffleOptions')));insert into private.question_keys values(s,v,(q->>'id')::uuid,k);pos:=pos+1;end loop;
for r in select value from jsonb_array_elements(p->'recipients') loop if not exists(select 1 from public.enrollments where class_id=c and student_id=(r->>'studentId')::uuid and active) then raise exception 'INVALID_RECIPIENT';end if;if coalesce((r->>'extraSeconds')::int,0)+(p->>'durationSeconds')::int>43200 or coalesce((r->>'closesAt')::timestamptz,(p->>'closesAt')::timestamptz)<=(p->>'opensAt')::timestamptz then raise exception 'INVALID_ACCOMMODATION';end if;insert into public.exam_recipients values(s,v,(r->>'studentId')::uuid,coalesce((r->>'extraSeconds')::int,0),coalesce((r->>'closesAt')::timestamptz,(p->>'closesAt')::timestamptz),false);insert into public.notifications(school_id,recipient_id,event_key,type,resource_id) values(s,(r->>'studentId')::uuid,'exam:'||v,'exam.assigned',v);end loop;
perform private.audit(s,'exam.published',v);return v;end$$;
create function public.start_attempt(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare e public.exam_versions;r public.exam_recipients;a public.attempts;ord jsonb;begin perform 1 from public.memberships where id=auth.uid()for update;select * into e from public.exam_versions where id=(p->>'versionId')::uuid for update;perform private.require_access(e.school_id);if private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into r from public.exam_recipients where version_id=e.id and student_id=auth.uid();if not found then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into a from public.attempts where version_id=e.id and student_id=auth.uid();if found then if a.status='in_progress'and a.writer is distinct from (p->>'writer')::uuid then raise exception 'WRITER_CONFLICT';end if;if a.status='in_progress'and now()>=a.deadline then a:=private.finalize(a.id);end if;return to_jsonb(a);end if;perform private.require_access(e.school_id,true);if r.exempt or e.status<>'published' or now()<e.opens_at or now()>=r.closes_at or (e.last_start_at is not null and now()>e.last_start_at) or private.active_attempt() then raise exception 'ATTEMPT_UNAVAILABLE';end if;
select jsonb_agg(jsonb_build_object('id',q.id,'options',(select jsonb_agg(o->'id' order by case when e.shuffle and coalesce((q.content->>'shuffleOptions')::boolean,false) then md5(auth.uid()::text||e.id||(o->>'id')) else ordinality::text end) from jsonb_array_elements(q.content->'options')with ordinality as options(o,ordinality))) order by q.content->>'section',case when e.shuffle then md5(auth.uid()::text||e.id||q.id) else lpad(q.position::text,5,'0') end) into ord from public.exam_questions q where q.version_id=e.id;
insert into public.attempts(school_id,version_id,student_id,deadline,writer,display_order) values(e.school_id,e.id,auth.uid(),least(now()+make_interval(secs=>e.duration_seconds+r.extra_seconds),r.closes_at),(p->>'writer')::uuid,ord) returning * into a;return to_jsonb(a);end$$;
create function private.finalize(aid uuid,forced boolean default false) returns public.attempts language plpgsql security definer set search_path='' as $$declare a public.attempts;q record;v int;begin select * into a from public.attempts where id=aid for update;if a.status<>'in_progress' then return a;end if;if not forced and now()<a.deadline then raise exception 'NOT_EXPIRED';end if;update public.attempts set status=case when now()>=deadline then 'expired' else 'submitted' end,finalized_at=least(now(),deadline),receipt=gen_random_uuid() where id=aid returning * into a;for q in select eq.*,k.key,ans.response from public.exam_questions eq join private.question_keys k on k.version_id=eq.version_id and k.question_id=eq.id left join public.answers ans on ans.attempt_id=aid and ans.question_id=eq.id where eq.version_id=a.version_id loop v:=private.objective_score(q.content,q.key,q.response);insert into private.grades(school_id,attempt_id,question_id,objective_score,final_score)values(a.school_id,aid,q.id,v,v)on conflict do nothing;if q.type='subjective' then insert into public.outbox(school_id,kind,dedup_key,payload)values(a.school_id,'subjective',aid||':'||q.id,jsonb_build_object('attemptId',aid,'questionId',q.id,'gradingVersion',1))on conflict do nothing;end if;end loop;return a;end$$;
create function public.save_answer(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;old public.answers;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;perform private.require_access(a.school_id);if a.student_id<>auth.uid() or private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;if now()>=a.deadline and a.status='in_progress' then a:=private.finalize(a.id);return jsonb_build_object('error','ATTEMPT_EXPIRED','receipt',a.receipt);end if;if a.status<>'in_progress' then return jsonb_build_object('error','ATTEMPT_FINALIZED');end if;if a.writer<>(p->>'writer')::uuid then return jsonb_build_object('error','WRITER_CONFLICT');end if;if not exists(select 1 from public.exam_questions where version_id=a.version_id and id=(p->>'questionId')::uuid) then raise exception 'INVALID_QUESTION';end if;select * into old from public.answers where attempt_id=a.id and question_id=(p->>'questionId')::uuid;if found and old.revision=(p->>'revision')::int and old.response=p->'response' then return to_jsonb(old);end if;if (p->>'revision')::int<>coalesce(old.revision,0)+1 then return jsonb_build_object('error','STALE_REVISION','currentRevision',old.revision);end if;insert into public.answers values(a.school_id,a.id,(p->>'questionId')::uuid,p->'response',(p->>'revision')::int,now())on conflict(attempt_id,question_id)do update set response=excluded.response,revision=excluded.revision,saved_at=excluded.saved_at returning * into old;return to_jsonb(old);end$$;
create function public.submit_attempt(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;perform private.require_access(a.school_id);if a.student_id<>auth.uid() or private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;if a.status='in_progress' and a.writer<>(p->>'writer')::uuid then raise exception 'WRITER_CONFLICT';end if;return to_jsonb(private.finalize(a.id,true));end$$;
create function public.review_grade(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare a public.attempts;q public.exam_questions;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;if not private.exam_teacher(a.version_id) or a.status='in_progress' then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into q from public.exam_questions where version_id=a.version_id and id=(p->>'questionId')::uuid;if (p->>'score')::int<0 or (p->>'score')::int>q.maximum then raise exception 'INVALID_SCORE';end if;update private.grades set final_score=(p->>'score')::int,feedback=p->>'feedback',reviewer=auth.uid(),revision=revision+1 where attempt_id=a.id and question_id=q.id and revision=(p->>'revision')::int;if not found then raise exception 'STALE_REVISION';end if;perform private.audit(a.school_id,'grade.reviewed',a.id,p->>'reason',jsonb_build_object('score',(p->>'score')::int));end$$;
create function public.review_details(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid;if not private.exam_teacher(a.version_id) then raise exception 'FORBIDDEN' using errcode='42501';end if;return jsonb_build_object('attempt',to_jsonb(a),'grades',(select jsonb_agg(to_jsonb(g))from private.grades g where attempt_id=a.id),'keys',(select jsonb_agg(to_jsonb(k))from private.question_keys k where version_id=a.version_id));end$$;
create function public.publish_result(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare a public.attempts;r public.results;t int;m int;sc jsonb;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;if not private.exam_teacher(a.version_id) or a.status='in_progress' then raise exception 'FORBIDDEN' using errcode='42501';end if;if exists(select 1 from private.grades where attempt_id=a.id and final_score is null) then raise exception 'UNREVIEWED';end if;select sum(g.final_score),sum(q.maximum),jsonb_agg(jsonb_build_object('questionId',q.id,'score',g.final_score,'maximum',q.maximum,'feedback',g.feedback,'topic',q.content->'primaryTopic'))into t,m,sc from private.grades g join public.exam_questions q on q.version_id=a.version_id and q.id=g.question_id where g.attempt_id=a.id;
insert into public.results(school_id,attempt_id,student_id,version_id,total,maximum,scores)values(a.school_id,a.id,a.student_id,a.version_id,t,m,sc)on conflict(attempt_id)do update set total=excluded.total,maximum=excluded.maximum,scores=excluded.scores,revision=results.revision+1,published_at=now()returning * into r;insert into private.result_revisions(result_id,revision,snapshot)values(r.id,r.revision,to_jsonb(r));insert into public.outbox(school_id,kind,dedup_key,payload)values(a.school_id,'insight',r.id||':'||r.revision,jsonb_build_object('studentId',a.student_id,'resultId',r.id,'revision',r.revision));insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)values(a.school_id,a.student_id,'result:'||r.id||':'||r.revision,'result.published',r.id);perform private.audit(a.school_id,'result.published',r.id,p->>'reason');return r.id;end$$;
